def unique_pieces(X, Y, picture):
    A, B = len(picture), len(piece[0]) if picture else 0
    pieces = []
    for i in range(A // X):
        for j in range(B // Y):
            piece = [picture[i * X + x][j * Y : j * Y + Y] for x in range(X)]
            # Generate all rotations of the piece
            rotations = [piece, [list(row) for row in zip(*piece[::-1])], piece[::-1], [list(row) for row in zip(*piece)][::-1]]
            # Normalize rotations to a canonical form (e.g., lex smallest)
            canonical = min(rotations, key=lambda r: (tuple(tuple(row) for row in r),))
            pieces.append(tuple(tuple(row) for row in canonical))
    return len(set(pieces)) == (A // X) * (B // Y)

